package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_visit_TriageGen2Test {

  private CheckGlobalThis checkGlobalThis;

  @Mock private NodeTraversal mockTraversal;
  @Mock private Node mockNode;
  @Mock private Node mockParent;
  @Mock private Compiler mockCompiler;
  @Mock private Node mockErrorNode;

  @Before
  public void setUp() {
    MockitoAnnotations.openMocks(this);
    checkGlobalThis = new CheckGlobalThis();

    // Using reflection to inject the compiler since it's a private field in typical JSComp checkers
    try {
      java.lang.reflect.Field compilerField = CheckGlobalThis.class.getDeclaredField("compiler");
      compilerField.setAccessible(true);
      compilerField.set(checkGlobalThis, mockCompiler);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  @Test
  public void testVisit_NoThisNoAssign() {
    when(mockNode.getType()).thenReturn(Token.NAME);

    checkGlobalThis.visit(mockTraversal, mockNode, mockParent);

    verify(mockCompiler, never()).report(any());
  }

  @Test
  public void testVisit_IsThisButShouldNotReport() {
    when(mockNode.getType()).thenReturn(Token.THIS);
    // We need to mock shouldReportThis. Since it's likely a protected/private method 
    // in the same class, we test the logic via the public entry point.
    // If shouldReportThis depends on parent or node state, we simulate that.
    // Assuming for this test case that the internal logic returns false.

    // To force shouldReportThis to false without mocking the method itself, 
    // we provide a parent that doesn't trigger the condition.
    checkGlobalThis.visit(mockTraversal, mockNode, mockParent);

    verify(mockCompiler, never()).report(any());
  }

  @Test
  public void testVisit_IsThisAndShouldReport() {
    when(mockNode.getType()).thenReturn(Token.THIS);
    // We need to ensure shouldReportThis returns true. 
    // This usually involves setting up the node/parent state correctly.
    // Since we can't see shouldReportThis, we assume a spy or specific state triggers it.

    CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
    org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(mockNode, mockParent);
    when(mockTraversal.makeError(any(), any(), any())).thenReturn(mockErrorNode);

    spyCheck.visit(mockTraversal, mockNode, mockParent);

    verify(mockTraversal).makeError(mockNode, any(), eq(GLOBAL_THIS));
    verify(mockCompiler).report(mockErrorNode);
  }

  @Test
  public void testVisit_IsAssignLhsChild() {
    // Setup the internal assignLhsChild field via reflection
    try {
      java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
      field.setAccessible(true);
      field.set(checkGlobalThis, mockNode);

      // Ensure it's not a THIS node to isolate the second IF
      when(mockNode.getType()).thenReturn(Token.NAME);

      checkGlobalThis.visit(mockTraversal, mockNode, mockParent);

      // Verify it was set to null
      Object result = field.get(checkGlobalThis);
      assert(result == null);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  @Test
  public void testVisit_IsThisAndIsAssignLhsChild() {
    // Test both branches being hit
    try {
      java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
      field.setAccessible(true);
      field.set(checkGlobalThis, mockNode);

      CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
      org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(mockNode, mockParent);
      when(mockNode.getType()).thenReturn(Token.THIS);
      when(mockTraversal.makeError(any(), any(), any())).thenReturn(mockErrorNode);

      spyCheck.visit(mockTraversal, mockNode, mockParent);

      verify(mockCompiler).report(any());
      Object result = field.get(spyCheck);
      assert(result == null);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  // Helper for equality check in verify
  private <T> T eq(T value) {
    return org.mockito.ArgumentMatchers.eq(value);
  }
}
